export const testSetIndex: TestSetIndex[] = allTestSets.map(ts => ({
  id: ts.id,
  title: ts.title,
  grade: ts.grade,
  difficulty: ts.difficulty,
  subject: ts.subject,
  passageCount: ts.passages.length,
  questionCount: ts.passages.reduce((acc, p) => acc + p.questions.length, 0),
}));

export function getTestSetById(id: string): PreGeneratedTestSet | undefined {
  return allTestSets.find(ts => ts.id === id);
}

export function getTestSetsForGrade(grade: GradeLevel): PreGeneratedTestSet[] {
  const gradeStr = grade as string;
  return allTestSets.filter(ts => {
    const tsGrade = ts.grade as string;
    if (gradeStr.includes('고등') && tsGrade.includes('고등')) return true;
    if (gradeStr.includes('중학') && tsGrade.includes('중학')) return true;
    if ((gradeStr.includes('5학년') || gradeStr.includes('6학년')) && (tsGrade.includes('5학년') || tsGrade.includes('6학년'))) return true;
    if ((gradeStr.includes('3학년') || gradeStr.includes('4학년')) && (tsGrade.includes('3학년') || tsGrade.includes('4학년'))) return true;
    if ((gradeStr.includes('1학년') || gradeStr.includes('2학년')) && !gradeStr.includes('고등') && !gradeStr.includes('중학') && (tsGrade.includes('1학년') || tsGrade.includes('2학년')) && !tsGrade.includes('고등') && !tsGrade.includes('중학')) return true;
    return false;
  });
}

export function getRandomTestSet(grade: GradeLevel, difficulty?: Difficulty): PreGeneratedTestSet | undefined {
  let candidates = getTestSetsForGrade(grade);
  if (difficulty) {
    const filtered = candidates.filter(ts => ts.difficulty === difficulty);
    if (filtered.length > 0) candidates = filtered;
  }
  if (candidates.length === 0) {
    candidates = getTestSetsForGrade(grade);
  }
  if (candidates.length === 0) {
    return allTestSets[0];
  }
  return candidates[Math.floor(Math.random() * candidates.length)];
}
